SELECT Count(*)
FROM   tblmi_noti AS noti
	LEFT JOIN tblmi_usr AS usr
		ON noti.REG_ID = usr.USR_ID
WHERE  noti.DEL_YN = 'N'

		and noti.SEQ = #{seq}


		and noti.NOTI_POPYN = #{noti_popyn}


		and noti.NOTI_SUB = #{noti_sub}


		and noti.NOTI_BODY = #{noti_sub}


		and noti.USR_GRP_CD=#{usr_grp_cd}


		and noti.NOTI_BGN_DTTM  <= #{noti_bgn_dttm}
		and #{noti_bgn_dttm}  <= noti.NOTI_END_DTTM

SELECT noti.seq            AS seq
		,noti.noti_sub      AS noti_sub
		,noti.noti_body     AS noti_body
		,noti.noti_bgn_dttm AS noti_bgn_dttm
		,noti.noti_end_dttm AS noti_end_dttm
		,noti.noti_popyn    AS noti_popyn
		,noti.noti_chk      AS noti_chk
		,usr.usr_email      AS reg_id
		,noti.reg_dt        AS reg_dt
		,noti.del_yn        AS del_yn
FROM   TBLMI_NOTI AS noti
	LEFT JOIN TBLMI_USR AS usr
			ON noti.reg_id = usr.usr_id
WHERE  noti.del_yn = 'N'

		and noti.SEQ = #{seq}


		and noti.USR_GRP_CD=#{usr_grp_cd}


		and noti.NOTI_POPYN = #{noti_popyn}


		and noti.NOTI_SUB = #{noti_sub}


		and noti.NOTI_BODY = #{noti_body}


		and noti.NOTI_BGN_DTTM  <= #{noti_bgn_dttm}
		and #{noti_bgn_dttm}  <= noti.NOTI_END_DTTM 


		and noti.SEQ NOT IN

			#{arr}


	order by noti.REG_DT desc

		LIMIT #{firstIndex, javaType=int}, #{recordCountPerPage, javaType=int}

